SELECT bkt, COUNT(*) n, LISTAGG(r,'~') WITHIN GROUP (ORDER BY r) r FROM (SELECT MOD(ROWNUM,200) bkt, v||'|'||dt||'|'||vt||'|'||ss||'|'||u||'|'||d||'|'||amt||'|'||nl r FROM (SELECT t.VOUCHER_NO v, TO_CHAR(MIN(t.VM_DATE),'YYYY-MM-DD') dt, MAX(t.VM_TYPE) vt, MAX(t.SUB_SYSTEM_CODE) ss, MAX(t.ENTRY_USER) u, SUBSTR(TRIM(TRANSLATE(MAX(t.DESCRIPTION),'|~'||CHR(10)||CHR(13)||CHR(9),'     ')),1,80) d, ROUND(SUM(t.DR_AMOUNT),2) amt, COUNT(*) nl FROM {P}GL_TRANSACTIONS_DETAILS t WHERE t.STATUS<>'C' AND t.VM_DATE>=DATE '{D0}' AND t.VM_DATE<DATE '{D1}' GROUP BY t.VOUCHER_NO HAVING MAX(t.ATTACH_FILE_PATH) IS NULL AND SUM(CASE WHEN UPPER(t.DESCRIPTION) LIKE '%FOR\_SHIFT%' ESCAPE '\' THEN 1 ELSE 0 END)=0)) GROUP BY bkt
